{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2135-09-10 23:00:00",
      "speaker": "Doctor",
      "text": "Hello, I'm Dr. Lee. I understand your GJ tube came out at the nursing home. We’re going to keep you here overnight to make sure everything’s stable before replacing it."
    },
    {
      "turn_number": 2,
      "time": "2135-09-10 23:05:00",
      "speaker": "Patient",
      "text": "Yes… tube out. Hurts leg."
    },
    {
      "turn_number": 3,
      "time": "2135-09-10 23:10:00",
      "speaker": "Doctor",
      "text": "I see you mentioned leg pain. We checked your vitals and labs, and you don’t have a fever or signs of infection. Your blood work shows your white count is a bit high, but we don’t see a clear source yet."
    },
    {
      "turn_number": 4,
      "time": "2135-09-10 23:15:00",
      "speaker": "Patient",
      "text": "No fever. Just leg."
    },
    {
      "turn_number": 5,
      "time": "2135-09-10 23:20:00",
      "speaker": "Doctor",
      "text": "We’ll monitor your leg. The swelling might be from lying on one side. We’ll also check your INR since you’re on warfarin for your atrial fibrillation. It was 1.9 on admission—slightly low, but we’re continuing your usual dose."
    },
    {
      "turn_number": 6,
      "time": "2135-09-10 23:25:00",
      "speaker": "Patient",
      "text": "Warfarin okay?"
    },
    {
      "turn_number": 7,
      "time": "2135-09-10 23:30:00",
      "speaker": "Doctor",
      "text": "Yes, we’re keeping it the same for now. Your diabetes and thyroid meds are also continuing as usual. We’re giving you pain medicine through the tube site if needed."
    },
    {
      "turn_number": 8,
      "time": "2135-09-11 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. We’re scheduling the GJ tube replacement today. An interventional radiologist will do it using imaging to guide the new tube into place."
    },
    {
      "turn_number": 9,
      "time": "2135-09-11 08:05:00",
      "speaker": "Patient",
      "text": "Will it hurt?"
    },
    {
      "turn_number": 10,
      "time": "2135-09-11 08:10:00",
      "speaker": "Doctor",
      "text": "They’ll use numbing medicine around the site. You shouldn’t feel much. You’ll be awake but won’t need sedation. The procedure usually goes smoothly."
    },
    {
      "turn_number": 11,
      "time": "2135-09-11 09:55:00",
      "speaker": "Doctor",
      "text": "The team just replaced your GJ tube. It went well—no complications. The tube is in the right spot and can be used for feeding right away."
    },
    {
      "turn_number": 12,
      "time": "2135-09-11 10:00:00",
      "speaker": "Patient",
      "text": "Good. Leg still swollen."
    },
    {
      "turn_number": 13,
      "time": "2135-09-11 10:05:00",
      "speaker": "Doctor",
      "text": "We noticed that. Your right leg and arm are both swollen. Since you have a history of clots, we recommend an ultrasound to check for a DVT. It might just be from positioning, but we want to be safe."
    },
    {
      "turn_number": 14,
      "time": "2135-09-11 10:10:00",
      "speaker": "Patient",
      "text": "Okay. Need it?"
    },
    {
      "turn_number": 15,
      "time": "2135-09-11 10:15:00",
      "speaker": "Doctor",
      "text": "We’ll arrange it soon. For now, your breathing is stable, lungs are clear, and your sacral ulcer looks clean. No signs of infection at the GJ site either."
    },
    {
      "turn_number": 16,
      "time": "2135-09-11 14:00:00",
      "speaker": "Doctor",
      "text": "The ultrasound is pending, but we’re planning to discharge you today to extended care. Your GJ tube is working, and you’re stable otherwise."
    },
    {
      "turn_number": 17,
      "time": "2135-09-11 14:05:00",
      "speaker": "Patient",
      "text": "Medicines same?"
    },
    {
      "turn_number": 18,
      "time": "2135-09-11 14:10:00",
      "speaker": "Doctor",
      "text": "Yes, all your medications continue as before. The rehab team will manage your warfarin and check your INR regularly to keep it in range."
    },
    {
      "turn_number": 19,
      "time": "2135-09-11 15:00:00",
      "speaker": "Doctor",
      "text": "We’re finalizing your discharge. Please watch for redness, swelling, or drainage at the GJ site. And the rehab team will follow up on the leg swelling."
    },
    {
      "turn_number": 20,
      "time": "2135-09-11 15:05:00",
      "speaker": "Patient",
      "text": "Thank you."
    },
    {
      "turn_number": 21,
      "time": "2135-09-11 15:10:00",
      "speaker": "Doctor",
      "text": "You're welcome. You did well. The feeding tube is secure, and we’ll make sure your care continues smoothly at the facility."
    },
    {
      "turn_number": 22,
      "time": "2135-09-11 15:30:00",
      "speaker": "Doctor",
      "text": "Just a quick update—your discharge orders are ready. You’ll go back on your regular schedule of tube feeds, medications, and monitoring."
    },
    {
      "turn_number": 23,
      "time": "2135-09-11 15:35:00",
      "speaker": "Patient",
      "text": "Back to routine?"
    },
    {
      "turn_number": 24,
      "time": "2135-09-11 15:40:00",
      "speaker": "Doctor",
      "text": "Exactly. Same meds, same feeds. Just make sure the rehab team checks your leg and your INR as planned."
    },
    {
      "turn_number": 25,
      "time": "2135-09-11 15:45:00",
      "speaker": "Patient",
      "text": "Understood."
    },
    {
      "turn_number": 26,
      "time": "2135-09-11 15:50:00",
      "speaker": "Doctor",
      "text": "We’ll have the transport team get you ready. You should be at the facility by late afternoon."
    },
    {
      "turn_number": 27,
      "time": "2135-09-11 16:00:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    },
    {
      "turn_number": 28,
      "time": "2135-09-11 16:10:00",
      "speaker": "Doctor",
      "text": "Take care. Let the rehab team know if anything changes—especially with the leg or the tube site."
    }
  ],
  "summary": {
    "admission_start": "2135-09-10 22:52:00",
    "admission_end": "2135-09-11 16:38:00",
    "summary_paragraph": "A 68-year-old male with a history of multiple strokes, tracheostomy, GJ tube, atrial fibrillation, and diabetes was admitted after pulling out his GJ tube at the nursing home. He was monitored overnight and found to have mild leukocytosis without an identifiable source and reported leg pain. The GJ tube was successfully replaced by interventional radiology without complications. His atrial fibrillation was managed with continued warfarin, and his INR was monitored. A stage 2 sacral ulcer was noted but remained stable. He developed new edema in the right lower and upper extremities, prompting a recommendation for DVT ultrasound. He remained stable throughout the admission and was discharged to extended care with all medications continued as before.",
    "problems": [
      "Gastrojejunal tube replacement",
      "Sacral decubitus ulcer stage 2",
      "Atrial fibrillation",
      "Leukocytosis, unspecified",
      "Diabetes with neurological manifestations",
      "Polyneuropathy in diabetes",
      "Tracheostomy status",
      "Peripheral vascular disease, unspecified",
      "Unspecified essential hypertension",
      "Unspecified acquired hypothyroidism"
    ]
  }
}
